// BIOS rotation: 0x10000 per turn, 8.8 scale; multiply each matrix row by its axis scale.
/* Exact memoization at the portable BIOS boundary. Original floating-point
 * operations remain the sole producer on a miss; no rounded lookup table,
 * approximate trigonometry is introduced. The angle/scale units follow the GBA BIOS.
 * AffineTerms is synchronous on the game's single cooperative thread. */
struct PeaqAffineMemo {
    s16 sx, sy;
    u16 rotation, valid;
    s32 pa, pb, pc, pd;
};
static struct PeaqAffineMemo peaq_affine_memo[8];
static unsigned peaq_affine_next;

for (unsigned i = 0; i < 8; ++i) {
    const struct PeaqAffineMemo *m = &peaq_affine_memo[i];
    if (m->valid && m->sx == xScale && m->sy == yScale && m->rotation == rotation) {
        *pa = m->pa; *pb = m->pb; *pc = m->pc; *pd = m->pd;
        return;
    }
}
// GBA BIOS angles use a 16-bit full turn; the low byte is ignored.
float angle = (rotation >> 8) * (float)(2.0 * M_PI) / 256.0f;

struct PeaqAffineMemo *m = &peaq_affine_memo[peaq_affine_next];
m->sx = xScale; m->sy = yScale; m->rotation = rotation;
m->pa = *pa; m->pb = *pb; m->pc = *pc; m->pd = *pd;
m->valid = 1;
peaq_affine_next = (peaq_affine_next + 1) & 7u;

/* MP2K BDPCM/reverse sample playback. The cache belongs to one channel call,
 * so overlapping cries cannot reuse another voice's decoded block. The last
 * encoded block may be short (--no-pad); never read past wav->size. */
typedef struct {
    u32 block;
    s8 decoded[64];
} PeaqDpcmBlock;

static s32 PeaqWaveSample(const struct WaveData *wav, s32 index,
                         PeaqDpcmBlock *cache)

    static const s8 delta[16] = {0,1,4,9,16,25,36,49,-64,-49,-36,-25,-16,-9,-4,-1};
    if (index < 0 || (u32)index >= wav->size)
        return 0;
    if (!wav->type)
        return wav->data[index];
    u32 block = (u32)index >> 6;
    if (cache->block != block)
    {
        const u8 *src = (const u8 *)wav->data + block * 33;
        u32 length = wav->size - block * 64;
        if (length > 64) length = 64;
        s32 sample = (s8)*src++;
        cache->decoded[0] = sample;
        for (u32 i = 1; i < length; ++i)
        {
            /* The first high nibble is unused. Thereafter: high, low. */
            u32 packed = src[i >> 1];
            u32 code = (i & 1) ? packed & 15 : packed >> 4;
            sample = (s8)(sample + delta[code]);
            cache->decoded[i] = sample;
        }
        cache->block = block;
    }
    return cache->decoded[(u32)index & 63];
}

static void SoundMainRAM_Unk1(struct SoundInfo *si, struct SoundChannel *chan,
                             s8 *dma, s32 n)
{
    struct WaveData *wav = chan->wav;
    const int reverse = (chan->type & TONEDATA_TYPE_REV) != 0;
    const int compressed = wav->type != 0;
    if (!(chan->statusFlags & SOUND_CHANNEL_SF_SPECIAL))
    {
        s32 offset = chan->currentPointer - wav->data;
        if (reverse) offset = wav->size - offset;
        chan->currentPointer = compressed ? (s8 *)(uintptr_t)offset : wav->data + offset;
        chan->statusFlags |= SOUND_CHANNEL_SF_SPECIAL;
    }
    s32 pos = compressed ? (s32)(uintptr_t)chan->currentPointer : chan->currentPointer - wav->data;
    if (reverse) --pos;
    s32 count = chan->count;
    u32 fw = chan->fw;
    u32 inc = (chan->type & TONEDATA_TYPE_FIX) ? 0x800000u : (u32)si->divFreq * chan->frequency;
    s32 loop = (!reverse && (chan->statusFlags & SOUND_CHANNEL_SF_LOOP) && wav->loopStart < wav->size) ? wav->size - wav->loopStart : 0;
    PeaqDpcmBlock cache;cache.block = ~0u;
    for (s32 i = 0; i < n && count > 0; ++i)
    {
        s32 base = PeaqWaveSample(wav,pos,&cache);
        s32 next = PeaqWaveSample(wav,pos+(reverse ? -1 : 1),&cache);
        s32 value = base + (s32)(((s64)(s32)fw * (next-base)) >> 23);
        dma[i] = (s8)(dma[i] + ((chan->envelopeVolumeRight * value) >> 8));
        dma[i+PCM_DMA_BUF_SIZE] = (s8)(dma[i+PCM_DMA_BUF_SIZE] + ((chan->envelopeVolumeLeft * value) >> 8));
        fw += inc;
        u32 advance = fw >> 23;
        fw &= ~0x3f800000u;
        if (!advance) continue;
        count -= advance;
        pos += reverse ? -(s32)advance : (s32)advance;
        if (count <= 0)
        {
            if (!loop) { chan->statusFlags = 0; count = 0; break; }
            do { count += loop; } while (count <= 0);
            pos = wav->size - count;
        }
    }
    chan->fw = fw;chan->count = count;
    if (reverse) ++pos;
    chan->currentPointer = compressed ? (s8 *)(uintptr_t)pos : wav->data + pos;

// src is the interpolation lookahead, not the current base sample.
// Match m4a_1.s: subtract one before retaining r3 for the next frame.
chan->currentPointer = src - 1;

/* Song streams live in the linked image; only cry streams are generated in
 * RAM. Checking this boundary also rejects a pointer into unrelated globals. */
extern const u8 __peaq_image_start[], __peaq_image_end[];
u32 peaq_audio_guard[8];
static u32 peaq_last_command;
static int PeaqSongBytes(const u8 *p,u32 n){
    uintptr_t a=(uintptr_t)p,lo=(uintptr_t)__peaq_image_start,hi=(uintptr_t)__peaq_image_end;
    if(a>=lo&&a<=hi&&n<=hi-a)return 1;
    lo=(uintptr_t)gPokemonCrySongs;hi=lo+sizeof(struct PokemonCrySong)*MAX_POKEMON_CRIES;
    return a>=lo&&a<=hi&&n<=hi-a;
}
static void PeaqBadTrack(struct MusicPlayerInfo *mi,struct MusicPlayerTrack *tr,u32 reason,const u8 *p){
    if(!peaq_audio_guard[0]){
        peaq_audio_guard[1]=reason;peaq_audio_guard[2]=(uintptr_t)p;
        peaq_audio_guard[3]=peaq_last_command;peaq_audio_guard[4]=(uintptr_t)tr;
        peaq_audio_guard[5]=mi?(uintptr_t)mi->songHeader:0;
        peaq_audio_guard[6]=tr->runningStatus;peaq_audio_guard[7]=tr->patternLevel;
    }
    if(peaq_audio_guard[0]!=0xffffffffu)++peaq_audio_guard[0];
    /* Stop only this track. Other music, game logic and save state survive. */
    ply_fine(mi,tr);
}

